import { FileUpload } from "./dragAndDrop";
import { UseReducerAndUseContext } from "./reducerAndContent";
import { RequestList } from "./request/RequestList";

function App() {
  const person = {
    firstName: 'John',
    lastName: 'Doe'
};

// Определяем новый свойство fullName с геттером и сеттером
Object.defineProperty(person, 'fullName', {
    get: function() {
        return `${this.firstName} ${this.lastName}`;
    },
    set: function(value) {
        const parts = value.split(' ');
        this.firstName = parts[0];
        this.lastName = parts[1];
    },
    enumerable: true, // Свойство будет перечисляемым
    configurable: true // Свойство можно будет переопределить
});

// Использование геттера
console.log(person); // Output: John Doe
  return (
    <div className="App">
      <UseReducerAndUseContext />
      <FileUpload />
      <RequestList />
    </div>
  );
}

export default App;
